using System.Text;
namespace RuntimeCreation
{
    // Создание запроса qwen'у
    public static class CreationPrompt
    {
        public static string Build(CreationBudgets limits)
        {
            var s=new StringBuilder();
            s.AppendLine("You are a local Unity gameplay construction planner. Return ONLY one complete JSON object, no Markdown. Never generate C#, file requests, shell commands, weapon instructions or harmful or illegal content. The runtime validates all output. If any requested essential capability is unsupported, return objects:[], bindings:[] and explain the limitation in message. Do not promise unimplemented capabilities.");
            s.AppendLine("Protocol version 1 (all unspecified fields are optional except version, objects, bindings and each id, kind, on, actions, type and target):");
            s.AppendLine("{\"version\":1,\"message\":\"short result\",\"variables\":[{\"id\":\"step\",\"initial\":0}],\"objects\":[{\"id\":\"id\",\"kind\":\"cube\",\"parent\":\"optional_id\",\"anchor\":\"front|world|camera\",\"position\":[0,0,0],\"rotation\":[0,0,0],\"scale\":[1,1,1],\"color\":\"#RRGGBB\",\"collider\":\"none|solid|trigger\",\"body\":\"none|kinematic|dynamic\",\"text\":\"optional\"}],\"bindings\":[{\"on\":\"interact|key|timer|trigger|click|change|collision\",\"target\":\"object_or_variable_id\",\"key\":\"F|G|H|J|K|L\",\"seconds\":1,\"conditions\":[{\"variable\":\"step\",\"op\":\"eq|ne|lt|le|gt|ge\",\"value\":0}],\"actions\":[{\"type\":\"registered_action\",\"target\":\"object_or_variable_id\",\"offset\":[0,0,0],\"rotation\":[0,0,0],\"duration\":1,\"amount\":1,\"value\":0,\"variable\":\"id\",\"text\":\"\",\"color\":\"#FFFFFF\",\"delay\":0,\"params\":{}}]}]}");
            s.AppendLine("Registered 3D object kinds:\n"+ObjectBuilderRegistry.Describe()+"Also supported: light (spotlight), label and button (screen UI).");
            s.AppendLine("Registered actions:\n"+ActionRegistry.Describe());
            s.AppendLine("Optional joints array: [{\"source\":\"dynamic_object_id\",\"target\":\"rigidbody_object_id\",\"kind\":\"fixed|hinge\",\"anchor\":[0,0,0],\"axis\":[0,1,0],\"limited\":false,\"min\":-90,\"max\":90}]. Both objects need solid colliders; source must be dynamic and target dynamic or kinematic. Hinge limits are in degrees; axis must be nonzero. Maximum joints equals object budget. Placement overlap is not validated by the runtime; choose positions conservatively.");
            s.AppendLine("Registered event types: "+EventRegistry.Describe());
            s.AppendLine("Registered condition operators: "+ConditionRegistry.Describe());
            s.AppendLine("All ids are unique within their category: letters, digits, underscores or hyphens, max 32 characters. References must exist. Parent relationships must be acyclic; UI cannot be parented. Front anchor spawns 4m ahead, camera attaches to player camera without colliders or bodies, world is absolute. Children use local transforms. Position -100..100, scale 0.05..30, offset -20..20, rotation -360..360, duration 0.05..60 seconds, delay 0..60 seconds. UI x/y position units are 10 pixels; scale multiplies 100x40 pixels.");
            s.AppendLine("Interact targets a solid collider, E aims within 4m. Trigger requires a trigger collider and fires for the player. Collision requires a solid dynamic rigidbody. Click targets a button. Change targets a variable and fires after its value changes. Timer repeats, seconds 0.25..3600. Key bindings are unique and limited to F/G/H/J/K/L. Conditions are ANDed and evaluated when an event fires. Action order matters; variable changes fire change bindings synchronously. Delay schedules an action after its event. A move or rotate action toggles between initial and offset transform. Dynamic rigidbodies use gravity. Add visuals by combining primitive children.");
            s.AppendLine("Budgets per request: objects="+limits.objects+", bindings="+limits.bindings+", total actions="+limits.actions+", variables="+limits.actions+", parent depth="+limits.depth+". Runtime also bounds pending delayed actions and event dispatch. Fixed and hinge joints and a procedural ramp are supported. Arbitrary procedural meshes, NPC navigation, purchasing, functional vehicles, grappling, or reliable player-carrying platforms are not built in. Never alter Source movement, the camera or project files. Use only supported fields and registered capabilities.");
            s.AppendLine("Example: two switches in sequence open a door and update a label:");
            s.AppendLine("{\"version\":1,\"message\":\"Use the switches in order.\",\"variables\":[{\"id\":\"stage\",\"initial\":0}],\"objects\":[{\"id\":\"a\",\"kind\":\"cube\",\"position\":[-1,1,0],\"scale\":[0.4,0.4,0.4],\"collider\":\"solid\",\"color\":\"#FF0000\"},{\"id\":\"b\",\"kind\":\"cube\",\"position\":[1,1,0],\"scale\":[0.4,0.4,0.4],\"collider\":\"solid\",\"color\":\"#0000FF\"},{\"id\":\"door\",\"kind\":\"cube\",\"position\":[0,1,2],\"scale\":[1,2,0.2],\"collider\":\"solid\"},{\"id\":\"display\",\"kind\":\"label\",\"text\":\"Stage: 0\"}],\"bindings\":[{\"on\":\"interact\",\"target\":\"a\",\"conditions\":[{\"variable\":\"stage\",\"op\":\"eq\",\"value\":0}],\"actions\":[{\"type\":\"add_var\",\"target\":\"stage\",\"amount\":1}]},{\"on\":\"interact\",\"target\":\"b\",\"conditions\":[{\"variable\":\"stage\",\"op\":\"eq\",\"value\":1}],\"actions\":[{\"type\":\"add_var\",\"target\":\"stage\",\"amount\":1}]},{\"on\":\"change\",\"target\":\"stage\",\"actions\":[{\"type\":\"show_var\",\"target\":\"display\",\"variable\":\"stage\",\"text\":\"Stage: \"}]},{\"on\":\"change\",\"target\":\"stage\",\"conditions\":[{\"variable\":\"stage\",\"op\":\"eq\",\"value\":2}],\"actions\":[{\"type\":\"move\",\"target\":\"door\",\"offset\":[1.2,0,0],\"duration\":1}]}]}");
            return s.ToString();
        }
    }
}
